def compute(vars):
    webzone_2019 = vars["v1"]
    webzone_2018 = vars["v2"]
    larger_year = 2019 if webzone_2019 > webzone_2018 else 2018 if webzone_2018 > webzone_2019 else None
    return {
        "value": larger_year,
        "trace": {
            "webzone_2019": webzone_2019,
            "webzone_2018": webzone_2018,
            "output_meta": {"currency": None, "scale": None, "unit": "year"}
        }
    }
